	input clk,
	input rst_n,
	input a,
	output match
	);

	reg [8:0] a_tem;
	reg match_f;
	reg match_b;

	always @(posedge clk or negedge rst_n)
		if (!rst_n)
			begin 
				match_f <= 1'b0;
			end
		else if (a_tem[8:6] == 3'b011)
			begin
				match_f <= 1'b1;
			end
		else 
			begin	
				match_f <= 1'b0;
			end

	always @(posedge clk or negedge rst_n)
		if (!rst_n)
			begin 
				match_b <= 1'b0;
			end
		else if (a_tem[2:0] == 3'b111)
			begin
				match_b <= 1'b1;
			end
		else 
			begin	
				match_b <= 1'b0;
			end

	always @(posedge clk or negedge rst_n)
		if (!rst_n)
			begin 
				a_tem <= 9'b0;
			end
		else 
			begin
				a_tem <= {a_tem[7:0],a};
			end

	assign match = match_b || match_f;
endmodule","editable":true}},"lens_instruction":"You repair a functional RTL bug in a repository using the specification, the visible directed test and its results. Only the files marked editable may change.","output_constraints":{"additional_keys_allowed":false,"full_source_only":true,"required_files":["rtl/sequence.sv"],"required_top_level_keys":["files","edit"]},"previous_attempts":[],"repair_experience":{"entries":[{"content":{"applied_patch":"--- a/rtl/sequence.sv
